// Only for the uncompressed statement PDFs generated by this portal.
export function statementExtractPdfPageStreams(pdfBytes){
  const source=new TextDecoder().decode(pdfBytes instanceof Uint8Array?pdfBytes:new Uint8Array(pdfBytes||[]));
  const streams=[];
  const pattern=/\d+ 0 obj\s*<< \/Length \d+ >>\s*stream\r?\n([\s\S]*?)\r?\nendstream/g;
  let match;
  while((match=pattern.exec(source)))streams.push(match[1]);
  if(!source.startsWith('%PDF-')||!streams.length)throw new Error('A statement PDF could not be read. Please preview again.');
  return streams;
}

export function statementBuildCombinedPdf(pdfParts){
  const pageStreams=[];
  for(const part of pdfParts||[])for(const stream of statementExtractPdfPageStreams(part))pageStreams.push(stream);
  if(!pageStreams.length)throw new Error('No statement pages were available for the preview.');
  const encoder=new TextEncoder(),chunks=[],offsets=[0];let length=0;
  const append=value=>{const bytes=encoder.encode(value);chunks.push(bytes);length+=bytes.length;};
  const object=(id,value)=>{offsets[id]=length;append(`${id} 0 obj\n${value}\nendobj\n`);};
  const kids=pageStreams.map((_,index)=>`${5+index*2} 0 R`).join(' ');
  append('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');
  object(1,'<< /Type /Catalog /Pages 2 0 R >>');
  object(2,`<< /Type /Pages /Kids [${kids}] /Count ${pageStreams.length} >>`);
  object(3,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');
  object(4,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>');
  pageStreams.forEach((stream,index)=>{
    const pageId=5+index*2,contentId=pageId+1;
    object(pageId,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${contentId} 0 R >>`);
    object(contentId,`<< /Length ${encoder.encode(stream).length} >>\nstream\n${stream}\nendstream`);
  });
  const count=4+pageStreams.length*2,xref=length;
  append(`xref\n0 ${count+1}\n0000000000 65535 f \n`);
  for(let id=1;id<=count;id++)append(String(offsets[id]).padStart(10,'0')+' 00000 n \n');
  append(`trailer\n<< /Size ${count+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`);
  const output=new Uint8Array(length);let offset=0;
  for(const chunk of chunks){output.set(chunk,offset);offset+=chunk.length;}
  return output;
}
